// Board-local SVG controls and a single additive RGB lens. No source-code inspection.
export function tivaRGBState(snapshot){const results=snapshot?.dc?.valid?snapshot.dc.ledResults:null,amps=pin=>Math.max(0,Number((results instanceof Map?results.get('$tiva-led-'+pin):results?.['$tiva-led-'+pin])?.current)||0),values=[amps('PF1'),amps('PF3'),amps('PF2')],channels=values.map(v=>v>1e-7?255:0);return{on:channels.some(Boolean),color:'rgb('+channels.join(',')+')',brightness:Math.min(1,Math.max(...values)/0.004),channels};}
export function toggleTivaControl(project,id,control){const c=project.components.find(c=>c.id===id&&c.type==='board'&&c.params.model==='ek-tm4c123gxl');if(!c)throw Error('Tiva kartı bulunamadı.');if(control==='RESET')return'reset';if(control==='SW1')project.settings.pressed=!project.settings.pressed;else if(control==='SW2')c.params.sw2=!c.params.sw2;else if(control==='POWER')c.params.powerSource=c.params.powerSource==='device'?'debug':'device';else throw Error('Tiva kontrolü geçersiz.');return'circuit';}
const button=(name,x,y)=>`<g class="tiva-control" role="button" tabindex="0" data-tiva-control="${name}" aria-label="Tiva ${name}${name==='SW1'?' PF4':name==='SW2'?' PF0':''}" ${name==='RESET'?'':'aria-pressed="false"'}><title>${name==='RESET'?'RESET · MCU sıfırla':name+' · tıkla: basılı tut / bırak'}</title><rect x="${x-12}" y="${y-9}" width="24" height="18" rx="2" fill="#bec6bc" stroke="#f0eedf" stroke-width=".6"/><rect x="${x-9.5}" y="${y-7}" width="19" height="14" rx="2" fill="#25322b"/><circle data-tiva-cap="${name}" cx="${x}" cy="${y}" r="6.2" fill="#506254" stroke="#7d9181" stroke-width=".6"/><path d="M${x-4} ${y-2}Q${x} ${y-5} ${x+4} ${y-2}" fill="none" stroke="#9dab9e" stroke-width=".65" pointer-events="none"/><rect class="tiva-hit" x="${x-14}" y="${y-11}" width="28" height="22" rx="3" fill="transparent" stroke="transparent"/></g>`;
export function tivaBoardOverlay(c,scale){return`<g data-tiva-board="${c.id}" transform="scale(${scale})"><g class="tiva-control" role="button" tabindex="0" data-tiva-control="POWER" aria-label="Tiva POWER SELECT DEBUG" aria-pressed="false"><title>POWER SELECT · DEBUG / DEVICE (iki USB beslemesi de modelde 3.3 V sağlar)</title><rect data-tiva-power-thumb x="25" y="20.5" width="12" height="7" rx="1" fill="#768c7c" stroke="#c8d9c9" stroke-width=".6"/><path data-tiva-power-grip d="M28 22v4m3-4v4m3-4v4" stroke="#dce7d8" stroke-width=".5"/><rect class="tiva-hit" x="7" y="17" width="36" height="14" rx="2" fill="transparent" stroke="transparent"/></g>${button('RESET',164,66)}${button('SW1',36,198)}${button('SW2',156,198)}<circle data-tiva-rgb-halo cx="96" cy="188" r="8" fill="#000" opacity="0" filter="url(#light)" pointer-events="none"/><circle data-tiva-rgb-lens cx="96" cy="188" r="3.3" fill="#68776b" stroke="#e9f1dd" stroke-width=".5" pointer-events="none"/><ellipse cx="95" cy="186.8" rx="1.1" ry=".6" fill="#fff" opacity=".45" pointer-events="none"/><title>Dahili RGB LED · PF1 kırmızı / PF2 mavi / PF3 yeşil</title></g>`;}
export function updateTivaBoardUI(root,project,snapshot){const rgb=tivaRGBState(snapshot);for(const node of root.querySelectorAll('[data-tiva-board]')){const c=project.components.find(c=>c.id===node.dataset.tivaBoard);if(!c)continue;for(const[name,on]of[['SW1',!!project.settings.pressed],['SW2',!!c.params.sw2]]){const control=node.querySelector('[data-tiva-control="'+name+'"]');control?.setAttribute('aria-pressed',String(on));node.querySelector('[data-tiva-cap="'+name+'"]')?.setAttribute('fill',on?'#afc8a7':'#506254');}const device=c.params.powerSource==='device';node.querySelector('[data-tiva-control="POWER"]')?.setAttribute('aria-label','Tiva POWER SELECT '+(device?'DEVICE':'DEBUG'));node.querySelector('[data-tiva-control="POWER"]')?.setAttribute('aria-pressed',String(device));node.querySelector('[data-tiva-power-thumb]')?.setAttribute('x',device?'12':'25');node.querySelector('[data-tiva-power-grip]')?.setAttribute('transform',device?'translate(-13 0)':'');const lens=node.querySelector('[data-tiva-rgb-lens]'),halo=node.querySelector('[data-tiva-rgb-halo]');lens?.setAttribute('fill',rgb.on?rgb.color:'#68776b');lens?.setAttribute('data-rgb-color',rgb.on?rgb.color:'off');halo?.setAttribute('fill',rgb.color);halo?.setAttribute('opacity',rgb.on?String(Math.max(.25,rgb.brightness)*.8):'0');}}
